import{_ as t,o,c as r,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/09-全新视角的解读.md","filePath":"books/attached/09-全新视角的解读.md","lastUpdated":1794316978000}'),n={name:"books/attached/09-全新视角的解读.md"};function l(d,a,c,_,p,i){return o(),r("div",null,[...a[0]||(a[0]=[e("h3",{id:"全新视角的解读",tabindex:"-1"},[s("全新视角的解读 "),e("a",{class:"header-anchor",href:"#全新视角的解读","aria-label":'Permalink to "全新视角的解读"'},"​")],-1),e("p",null,"让我们来回顾一下密友塔玛拉的故事，并用一种全新的思路来审视它。依恋研究中，格雷格就是回避型依恋风格的典型，他的种种行为细节都精确印证了这一点。包括他的思维、行为以及与世界联结的方式。回避型依恋风格预示了他在恋爱关系中的各个阶段，所表现出的疏离、对塔玛拉的吹毛求疵以及制造争端等行为，还包括他最大的难点：说一句“我爱你”。研究结果非常有意思，纵使他想要靠近她，也会感觉一种力量在将她推开，并不是因为他“不爱她”，也不是因为他认为“对方不够优秀（就像塔玛拉得出的结论一样）”。恰恰相反，他之所以将她推开，正是因为他感觉到了亲密与爱恋的与日俱增。",-1),e("p",null,"而这一切也表明，塔玛拉并不是个例。依恋理论将她的这种行为、思维以及反应，都归纳为典型的焦虑型依恋风格，她的表现同样也准确地印证了这种风格。这种依恋风格决定了在面对格雷格的疏离时，她会愈加紧逼；也预示了她难以集中精力工作，她日思夜想着恋爱关系，以及她对格雷格所做一切的过度敏感。同样地，这种依恋风格决定了即使它下定决心想要与对方分手，也完全无力鼓起勇气付诸行动。这也就可以解释，她为什么无视自己的判断和朋友的建议，倾尽所能只为贴近格雷格。这个理论所揭示的最重要一点，是为什么塔玛拉和格雷格明明还深爱着对方，却难以将恋爱维系下去。他们俩使用着完全不同的话语体系，一步步激怒着对方的天性。她青睐于身心的亲密，而他却钟爱于保持独立，并羞于亲昵。他们简直将理论中描述的两个极端，演绎得惊人地准确。研究者想要了解到爱侣们最亲密的瞬间，以及最私密的想法，仿佛是件非常难的事情。心理学方法总归是有些模糊，解释的余地非常广阔。但是这套理论却致力于为那些看起来毫无章法可循训的亲密关系，提供一种精准而有理有据的洞悉方式。",-1),e("p",null,"虽然对人们来说，想要改变依恋风格是有可能的，大概平均每四个人里面，就有一个能够把依恋风格四年一换。然而这种改变总在人们的无意识中发生，因此人们往往意识不到这种改变（更不用说改变的原因了）。于是我们想到，若是能够帮助人们找到一种方法来控制这种转变，岂不是件好事吗？若是他们能够有意识地让自己的依恋风格向安全型转变，而非为生活事件所支配，事情是否会变得不同呢？",-1),e("p",null,"对我们来说，了解这三种依恋风格就是拓宽了视野。我们可以发现，成人依恋行为是无处不在的。于是我们在看待自己或是周围朋友的恋爱关系时，会产生一种新的视角。通过将各种依恋风格套用到我们的来访者、同事以及朋友身上，我们会对他们的亲密关系产生全新而且更为清晰的解读。他们的行为将不再那么难以捉摸，在一定情景之下或将可以预测。",-1)])])}const h=t(n,[["render",l]]);export{f as __pageData,h as default};
